import json
import numpy as np
import pandas as pd

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

df = pd.read_excel(DATA_FILE, sheet_name="PVC")
df.columns = [str(c).strip() for c in df.columns]

temperature_col = next(c for c in df.columns if "temperature" in c.lower())
weight_col = next(c for c in df.columns if "weight" in c.lower() and "deriv" not in c.lower())

data = df[[temperature_col, weight_col]].apply(pd.to_numeric, errors="coerce").dropna()
data = data.sort_values(temperature_col)

def weight_at(temp):
    return float(np.interp(temp, data[temperature_col].to_numpy(), data[weight_col].to_numpy()))

weight_200 = weight_at(200.0)
weight_400 = weight_at(400.0)
mass_loss = weight_200 - weight_400

option = {
