        "left": "center",
        "textStyle": {"fontFamily": "Noto Sans CJK KR", "fontSize": 18, "color": "#222"},
        "subtextStyle": {"fontFamily": "Noto Sans CJK KR", "fontSize": 13, "color": "#555"}
    },
    "tooltip": {"trigger": "axis"},
